/* ---------- 通用工具 ---------- */

function _agTxt(s) {
  if (s == null) return '';
  return String(s)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function _agBody(raw) {
  return Array.isArray(raw) ? raw[0] : raw;
}

function _agJson(raw) {
  var v = _agBody(raw);
  if (v == null) return null;
  if (typeof v === 'string') {
    try { return JSON.parse(v); } catch (e) { return null; }
  }
  return v;
}

function _agNum(n, d) {
  var v = parseInt(n, 10);
  return isNaN(v) ? (d || 0) : v;
}

function _agJoin(base, q) {
  return String(base) + (String(base).indexOf('?') >= 0 ? '&' : '?') + q;
}

function _agIso(t) {
  return String(t || '').replace(' ', 'T');
}

function _agTrimSlash(s) {
  return String(s || '').replace(/\/+$/, '');
}

function _agMeta(urls, processor) {
  return {
    __meta: true,
    __fetchUrls: urls,
    __fetchResponseType: 'json',
    __fetchConcurrency: 6,
    __processor: processor
  };
}

function _agResolve(base, rel) {
  var r = String(rel || '');
  if (/^https?:\/\//i.test(r)) return r;
  if (r.indexOf('//') === 0) return 'https:' + r;
  if (r.indexOf('/') === 0) {
    var m = String(base).match(/^https?:\/\/[^\/]+/);
    return m ? m[0] + r : r;
  }
  var cut = String(base).lastIndexOf('/');
  return base.slice(0, cut + 1) + r;
}

function _agEncPath(u) {
  return String(u || '').replace(/[^A-Za-z0-9\-._~:\/\?#\[\]@!$&'()*+,;=%]/g, function (c) {
    return encodeURIComponent(c);
