/* ---------- 列表条目构造与合并（第 2 段）---------- */

function _agMacItem(key, it) {
  var apiId = key + '~' + (it.vod_id != null ? it.vod_id : '');
  var cls = String(it.vod_class || '');
  return {
    id: apiId,
    title: String(it.vod_name || '').trim(),
    cover: String(it.vod_pic || ''),
    detailUrl: AG_BASE + '/detail/' + apiId,
    status: String(it.vod_remarks || ''),
    year: String(it.vod_year || ''),
    tags: cls ? cls.split(',') : [],
    updatedAt: _agIso(it.vod_time),
    _t: String(it.vod_time || ''),
    _h: _agNum(it.vod_hits, 0),
    _s: _agNum(parseFloat(it.vod_score), 0),
    _c: cls,
    _ty: String(it.type_id != null ? it.type_id : '')
  };
}

function _agSuggestItem(s) {
  var key = String(s.sourceKey || '');
  var apiId = key + '~' + (s.vodId != null ? s.vodId : '');
  var cls = String(s.class || '');
  return {
    id: apiId,
    title: String(s.name || '').trim(),
    cover: String(s.pic || s.picThumb || ''),
    detailUrl: AG_BASE + '/detail/' + apiId,
    status: String(s.remarks || ''),
    year: String(s.year || ''),
    tags: cls ? cls.split(',') : [],
    updatedAt: _agIso(s.time),
    _t: _agIso(s.time || ''),
    _h: _agNum(s.hits, 0),
    _s: _agNum(parseFloat(s.score), 0),
    _c: cls,
    _ty: ''
  };
}

/* 去重（同名同年保第一条）+ 清理 _ 开头内部字段 + 截断 */
function _agFinish(items, cap) {
  var seen = {};
  var out = [];
  for (var i = 0; i < items.length; i++) {
    var it = items[i];
    if (!it || !it.id || !it.title) continue;
    var nk = it.title + '|' + (it.year || '');
    if (seen[nk]) continue;
    seen[nk] = 1;
    var clean = {};
    for (var f in it) {
      if (f.charAt(0) !== '_') clean[f] = it[f];
    }
    out.push(clean);
    if (cap > 0 && out.length >= cap) break;
  }
  return out;
}

/* 扇出响应展开：raws 顺序对齐 AG_FANOUT，失败项（null）跳过 */
function _agSpread(raws) {
  var out = [];
  if (!Array.isArray(raws)) return out;
  for (var j = 0; j < raws.length && j < AG_FANOUT.length; j++) {
    var data = _agJson(raws[j]);
    if (!data || !data.list) continue;
    var key = AG_FANOUT[j].k;
    var list = data.list;
    for (var t = 0; t < list.length; t++) {
      if (list[t]) out.push(_agMacItem(key, list[t]));
    }
  }
  return out;
}

function _agSortBy(all, key) {
  if (key === 'hit') {
    all.sort(function (a, b) { return (b._h || 0) - (a._h || 0); });
  } else if (key === 'score') {
    all.sort(function (c, d) { return (d._s || 0) - (c._s || 0); });
  } else {
    all.sort(function (a, b) { return String(b._t || '').localeCompare(String(a._t || '')); });
  }
}

/* ---------- 端点：latest ---------- */

function parseList(raw, context) {
  AG_BASE = _agTrimSlash(context && context.baseUrl);
  AG_PAGE = _agNum(context && context.page, 1);
  var urls = [];
  for (var i = 0; i < AG_FANOUT.length; i++) {
    urls.push(_agJoin(AG_FANOUT[i].a, 'ac=videolist&pg=' + AG_PAGE));
  }
  return _agMeta(urls, 'procLatest');
}

function procLatest(raws) {
  var all = _agSpread(raws);
  _agSortBy(all, 'time');
  return _agFinish(all, 40);
}

/* ---------- 端点：search ---------- */

/* 路由已预取站方聚合 suggest（responseType json → raw 即解析对象），第 1 页并入 */
function parseSearch(raw, context) {
  AG_BASE = _agTrimSlash(context.baseUrl);
  AG_PAGE = _agNum(context.page, 1);
  var kw = String(context.keyword || '').trim();
  AG_SUGGEST = (raw && raw.list) ? raw.list : [];
  var urls = [];
  for (var i = 0; i < AG_FANOUT.length; i++) {
    urls.push(_agJoin(AG_FANOUT[i].a, 'ac=videolist&wd=' + encodeURIComponent(kw) + '&pg=' + AG_PAGE));
  }
  return _agMeta(urls, 'procSearch');
}

function procSearch(raws) {
  var all = [];
  if (AG_PAGE === 1 && AG_SUGGEST && AG_SUGGEST.length) {
    for (var i = 0; i < AG_SUGGEST.length; i++) {
      var s = AG_SUGGEST[i];
      if (s && AG_LOOKUP[String(s.sourceKey || '')]) all.push(_agSuggestItem(s));
    }
  }
  var fan = _agSpread(raws);
  for (var j = 0; j < fan.length; j++) all.push(fan[j]);
  _agSortBy(all, 'time');
  return _agFinish(all, 60);
}

/* ---------- 端点：category ---------- */

function parseCategory(raw, context) {
  AG_BASE = _agTrimSlash(context.baseUrl);
  AG_PAGE = _agNum(context.page, 1);
  AG_CAT = String(context.category || '');
  AG_AREA = String(context.area || '');
  AG_YEAR = String(context.year || '');
  AG_ORDER = String(context.order || '');
  var by = AG_ORDER === 'time' ? 'time' : (AG_ORDER === 'hit' ? 'hits' : (AG_ORDER === 'score' ? 'score' : ''));
  var urls = [];
  for (var i = 0; i < AG_FANOUT.length; i++) {
    var q = 'ac=videolist&pg=' + AG_PAGE;
    if (AG_AREA) q += '&area=' + encodeURIComponent(AG_AREA);
    if (AG_YEAR) q += '&year=' + encodeURIComponent(AG_YEAR);
    if (by) q += '&by=' + by;
    urls.push(_agJoin(AG_FANOUT[i].a, q));
  }
  return _agMeta(urls, 'procCategory');
}

/* 单波扇出 + 静态类型表判定分类（未知类型走 class 文本正则兜底），不匹配即过滤 */
function procCategory(raws) {
  var all = [];
  var spread = _agSpread(raws);
  for (var i = 0; i < spread.length; i++) {
    var rec = spread[i];
    var tbl = (AG_TT && AG_TT[rec.id.slice(0, rec.id.lastIndexOf('~'))]) || {};
    var cat = tbl[rec._ty] || _agCatOfText(rec._c);
    if (cat === AG_CAT) all.push(rec);
  }
  _agSortBy(all, AG_ORDER || 'time');
  return _agFinish(all, 40);
}

/* 分类文本兜底正则（取自聚合站前端同类映射） */
function _agCatOfText(text) {
  var s = String(text || '');
  if (!s) return '';
  if (/电影|动作片|爱情片|喜剧片|科幻片|恐怖片|剧情片|战争片|惊悚片|犯罪片|悬疑片|奇幻片|灾难片|纪录片|动画电影/.test(s)) return '电影';
  if (/电视剧|连续剧|剧集|国产剧|港剧|台剧|日剧|韩剧|美剧|泰剧|海外剧|日韩剧|马泰剧/.test(s)) return '电视剧';
  if (/动漫|动画|番剧|少儿/.test(s)) return '动漫';
  if (/综艺|真人秀|脱口秀|晚会/.test(s)) return '综艺';
  return '';
}

/* ---------- 端点：detail / episodes / video（第 3 段）---------- */

function _agSplitId(apiId) {
  var s = String(apiId || '');
  var cut = s.lastIndexOf('~');
  return cut > 0 ? { key: s.slice(0, cut), vodId: s.slice(cut + 1) } : { key: '', vodId: '' };
}

