/* 三段式选集合并：$$$ 分线路 / # 分集 / $ 分标题与地址。
   线路按「首集直连媒体优先」稳定排序，跨线路按集号去重（先到先得）。 */
function procEpisodes(raw) {
  var data = _agJson(raw);
  var v = data && data.list && data.list[0];
  if (!v) return [];
  var froms = String(v.vod_play_from || '').split('$$$');
  var urllines = String(v.vod_play_url || '').split('$$$');
  var lines = [];
  for (var li = 0; li < urllines.length; li++) {
    var name = _agTxt(froms[li] || '');
    if (!name) name = '线路' + (li + 1);
    var segs = String(urllines[li] || '').split('#');
    var eps = [];
    for (var ei = 0; ei < segs.length; ei++) {
      var seg = segs[ei];
      if (!seg) continue;
      var cut = seg.indexOf('$');
      var t = cut >= 0 ? seg.slice(0, cut) : '';
      var u = cut >= 0 ? seg.slice(cut + 1) : '';
      if (u.indexOf('http') !== 0) continue;
      eps.push({ t: _agTxt(t) || ('第' + (ei + 1) + '集'), u: u });
    }
    if (eps.length) lines.push({ name: name, eps: eps });
  }
  function _agDirectScore(u) {
    return /\.(m3u8|mp4)(\?|#|$)/i.test(String(u || '')) ? 0 : 1;
  }
  lines.sort(function (a, b) {
    var sa = _agDirectScore(a.eps[0] && a.eps[0].u);
    var sb = _agDirectScore(b.eps[0] && b.eps[0].u);
    return sa - sb;
  });
  var seen = {};
  var out = [];
  for (var li2 = 0; li2 < lines.length; li2++) {
    var eps2 = lines[li2].eps;
    for (var ei2 = 0; ei2 < eps2.length; ei2++) {
      var e = eps2[ei2];
      var nk = String(e.t).replace(/\D/g, '') || String(ei2 + 1);
      if (seen[nk]) continue;
      seen[nk] = 1;
      out.push({
        id: AG_ID + '#' + li2 + '#' + ei2,
        title: e.t,
        url: _agEncPath(e.u),
        number: _agNum(nk, ei2 + 1) || (ei2 + 1)
      });
    }
  }
  return out;
}

/* 播放：预取体是集 URL 的响应（直链=播放列表文本→直接回原 URL；中转页→解析真实地址） */
function parseVideo(raw, context) {
  var u = String((context && context.url) || '');
  AG_BASE = _agTrimSlash(context && context.baseUrl);
  var body = typeof raw === 'string' ? raw : '';
  if (body.indexOf('#EXTM3U') >= 0) return u;
  /* 形态A：var main = "/xxx/index.m3u8?sign=..."（根相对，按中转页 origin 补全） */
  var m = body.match(/var\s+main\s*=\s*"([^"]+)"/);
  if (m) return _agResolve(u, m[1]);
  /* 形态B：player_aaaa 配置对象（url/encrypt，与内置影视源同款） */
  var i = body.indexOf('player_aaaa');
  if (i >= 0) {
    var k = body.indexOf('{', i);
    if (k >= 0) {
      var depth = 0;
      var end = -1;
      for (var j = k; j < body.length; j++) {
        var ch = body.charAt(j);
        if (ch === '{') depth++;
        else if (ch === '}') {
          depth--;
          if (depth === 0) { end = j + 1; break; }
        }
      }
      if (end > 0) {
        var cfg = null;
        try { cfg = JSON.parse(body.substring(k, end)); } catch (e2) { cfg = null; }
        if (cfg && cfg.url) {
          var v2 = String(cfg.url);
          var enc = cfg.encrypt || 0;
          if (enc == 2) {
            try { v2 = atob(v2); } catch (e3) { }
            try { v2 = decodeURIComponent(v2); } catch (e4) { }
          } else if (enc == 1) {
            try { v2 = decodeURIComponent(v2); } catch (e5) { }
          }
          if (v2.indexOf('http') === 0) return v2;
          return _agResolve(u, v2);
        }
      }
    }
  }
  /* 兜底：正文第一个 m3u8/mp4 直链 */
  var any = body.match(/https?:\/\/[^"'\s,]+?\.(?:m3u8|mp4)[^"'\s,]*/i);
  if (any) return any[0];
  return u;
}
